#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    cin >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    int count = (int)m + 1;
    vector<vector<int>> adj(count + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    vector<int> parent(count + 1, 0), order = {1};
    parent[1] = -1;
    for (size_t i = 0; i < order.size(); i++) {
        int v = order[i];
        for (int w : adj[v]) {
            if (w != parent[v]) {
                parent[w] = v;
                order.push_back(w);
            }
        }
    }
    vector<int> sizes(count + 1, 1), biggestChild(count + 1, 0);
    for (size_t i = order.size(); i-- > 1;) {
        int v = order[i];
        sizes[parent[v]] += sizes[v];
        biggestChild[parent[v]] = max(biggestChild[parent[v]], sizes[v]);
    }
    bool first = true;
    for (int v = 1; v <= count; v++) {
        if (2 * max(count - sizes[v], biggestChild[v]) <= count) {
            cout << (first ? "" : " ") << v;
            first = false;
        }
    }
    cout << "\n";

    return 0;
}

