import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) m + 1;
        List<List<Integer>> adj = new ArrayList<>();
        for (int v = 0; v <= count; v++) adj.add(new ArrayList<>());
        for (long[] e : edges) {
            adj.get((int) e[0]).add((int) e[1]);
            adj.get((int) e[1]).add((int) e[0]);
        }
        int[] parent = new int[count + 1];
        parent[1] = -1;
        List<Integer> order = new ArrayList<>();
        order.add(1);
        for (int i = 0; i < order.size(); i++) {
            int v = order.get(i);
            for (int w : adj.get(v)) {
                if (w != parent[v]) {
                    parent[w] = v;
                    order.add(w);
                }
            }
        }
        int[] sizes = new int[count + 1];
        Arrays.fill(sizes, 1);
        int[] biggestChild = new int[count + 1];
        for (int i = order.size() - 1; i >= 1; i--) {
            int v = order.get(i);
            sizes[parent[v]] += sizes[v];
            biggestChild[parent[v]] = Math.max(biggestChild[parent[v]], sizes[v]);
        }
        StringBuilder out = new StringBuilder();
        for (int v = 1; v <= count; v++) {
            if (2 * Math.max(count - sizes[v], biggestChild[v]) <= count) out.append(out.length() > 0 ? " " : "").append(v);
        }
        System.out.println(out);
    }
}
